create extension if not exists pgcrypto;
create type public.user_role as enum ('couple','vendor','planner','family');
create type public.rsvp_status as enum ('pending','confirmed','declined');
create type public.booking_status as enum ('requested','quoted','accepted','declined','cancelled','completed');
create type public.expense_status as enum ('pending','paid');
create type public.collaborator_role as enum ('view_only','edit','budget_access');
create table public.users(id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,role public.user_role default 'couple',created_at timestamptz default now());
create table public.weddings(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.users(id) on delete cascade,partner_name text,wedding_date date,guest_count integer,city text,budget numeric(12,2),style text,created_at timestamptz default now());
create table public.guests(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,name text not null,relationship text,side text,plus_one boolean default false,dietary_restrictions text,rsvp public.rsvp_status default 'pending',table_assignment text,created_at timestamptz default now());
create table public.vendors(id uuid primary key default gen_random_uuid(),owner_id uuid references public.users(id) on delete set null,business_name text not null,category text,city text,description text,rating numeric(2,1),price_min numeric(12,2),price_max numeric(12,2),portfolio jsonb default '[]'::jsonb,packages jsonb default '[]'::jsonb,created_at timestamptz default now());
create table public.bookings(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,vendor_id uuid not null references public.vendors(id) on delete cascade,status public.booking_status default 'requested',quote_amount numeric(12,2),deposit_amount numeric(12,2),balance_amount numeric(12,2),deposit_due date,balance_due date,created_at timestamptz default now());
create table public.budget_categories(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,name text not null,allocated numeric(12,2) default 0,created_at timestamptz default now());
create table public.expenses(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,category_id uuid references public.budget_categories(id) on delete set null,vendor_name text,description text,amount numeric(12,2) not null,status public.expense_status default 'pending',due_date date,created_at timestamptz default now());
create table public.tasks(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,title text not null,due_date date,phase text,assignee_id uuid references public.users(id) on delete set null,completed boolean default false,created_at timestamptz default now());
create table public.timeline_events(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,title text not null,starts_at timestamptz,ends_at timestamptz,location text,responsible_person text,notes text,created_at timestamptz default now());
create table public.mood_board_items(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,category text,image_url text not null,note text,created_at timestamptz default now());
create table public.messages(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,booking_id uuid references public.bookings(id) on delete cascade,sender_id uuid not null references public.users(id) on delete cascade,body text not null,created_at timestamptz default now());
create table public.invitations(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,title text,template text,asset_url text,sent_at timestamptz,created_at timestamptz default now());
create table public.collaborators(id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,role public.collaborator_role not null,created_at timestamptz default now(),unique(wedding_id,user_id));
create or replace function public.is_wedding_member(target_wedding uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.weddings w where w.id=target_wedding and w.owner_id=auth.uid()) or exists(select 1 from public.collaborators c where c.wedding_id=target_wedding and c.user_id=auth.uid()); $$;
alter table public.users enable row level security;alter table public.weddings enable row level security;alter table public.guests enable row level security;alter table public.vendors enable row level security;alter table public.bookings enable row level security;alter table public.budget_categories enable row level security;alter table public.expenses enable row level security;alter table public.tasks enable row level security;alter table public.timeline_events enable row level security;alter table public.mood_board_items enable row level security;alter table public.messages enable row level security;alter table public.invitations enable row level security;alter table public.collaborators enable row level security;
create policy "users own profile" on public.users for all using(id=auth.uid()) with check(id=auth.uid());
create policy "wedding members" on public.weddings for all using(owner_id=auth.uid() or public.is_wedding_member(id)) with check(owner_id=auth.uid());
create policy "wedding scoped guests" on public.guests for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id));
create policy "vendors public read" on public.vendors for select using(true);create policy "vendors owner write" on public.vendors for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "wedding scoped bookings" on public.bookings for all using(public.is_wedding_member(wedding_id) or exists(select 1 from public.vendors v where v.id=vendor_id and v.owner_id=auth.uid())) with check(public.is_wedding_member(wedding_id) or exists(select 1 from public.vendors v where v.id=vendor_id and v.owner_id=auth.uid()));
create policy "wedding scoped budget categories" on public.budget_categories for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id));
create policy "wedding scoped expenses" on public.expenses for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id));
create policy "wedding scoped tasks" on public.tasks for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id));
create policy "wedding scoped timeline" on public.timeline_events for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id));
create policy "wedding scoped moodboard" on public.mood_board_items for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id));
create policy "wedding scoped messages" on public.messages for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id) and sender_id=auth.uid());
create policy "wedding scoped invitations" on public.invitations for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id));
create policy "wedding scoped collaborators" on public.collaborators for all using(public.is_wedding_member(wedding_id)) with check(public.is_wedding_member(wedding_id));
insert into storage.buckets(id,name,public) values('wedding-assets','wedding-assets',true) on conflict(id) do nothing;
create policy "public wedding asset read" on storage.objects for select using(bucket_id='wedding-assets');
